export const POOL_LEVELS = Object.freeze(plans.map(([id, name, cue, balls, lesson], rank20) => Object.freeze({
  id: `pool-${id}`, name, rank20, cue: Object.freeze(cue),
  balls: Object.freeze(balls.map(position => Object.freeze(position))), lesson,
})));

export function poolLevel(rank20) {
  return POOL_LEVELS[Math.max(0, Math.min(19, Math.floor(Number(rank20) || 0)))];
}
